import{_ as a,o,c as t,a2 as n}from"./chunks/framework.CiKk3sJz.js";const p=JSON.parse('{"title":"漫画 · 第 44 话 Web Components 入门：浏览器原生组件化","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.44-web-components.md","filePath":"comics/html/EP.44-web-components.md","lastUpdated":1792579602000}'),l={name:"comics/html/EP.44-web-components.md"};function r(c,e,d,s,i,h){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="漫画-·-第-44-话-web-components-入门-浏览器原生组件化" tabindex="-1">漫画 · 第 44 话 Web Components 入门：浏览器原生组件化 <a class="header-anchor" href="#漫画-·-第-44-话-web-components-入门-浏览器原生组件化" aria-label="Permalink to &quot;漫画 · 第 44 话 Web Components 入门：浏览器原生组件化&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/16-web-components">docs/html/16-web-components.md</a> ｜ 原画：<a href="./EP.44-web-components.svg">EP.44-web-components.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。团队维护的 React 组件库，隔壁 Vue 项目想用只能重新实现一遍——同一个按钮写两套，升级还要同步改两处，样式冲突靠 BEM 命名苦苦支撑。</li><li><strong>标签君</strong>：HTML5 结构师，搬出浏览器原生三件套：<code>&lt;template&gt;</code> 惰性模板、<code>&lt;slot&gt;</code> 插槽分发、<code>customElements.define</code> 自定义元素——零依赖、跨框架，React/Vue/Angular 都能直接用。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>框架组件生态各自为战：React 的 <code>&lt;NeonButton /&gt;</code> 到了 Vue 项目就是废铁。Web Components 把组件化能力下沉到浏览器本身——template 定义惰性模板，slot 做内容分发，customElements.define 注册新标签，Shadow DOM 提供样式隔离。写一次，到处运行，与框架无关。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>React 组件 Vue 用不了，同个按钮写两套、升级同步改两处；样式冲突靠 BEM 命名纪律维持；跨框架复用等于重写。框架锁定了组件生态，复用成本随团队技术栈数量线性膨胀。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p><code>&lt;template&gt;</code> 里的内容不渲染、脚本不执行，克隆后才激活；<code>customElements.define(&#39;neon-card&#39;, Class)</code> 注册新标签，标签名必须含短横线以避免与原生元素冲突；Shadow DOM 完全隔离内外样式，穿透靠 CSS 自定义属性 <code>--*</code>。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大场景：跨框架按钮（React/Vue/原生 HTML 三处直接用）、Shadow DOM 封装（内外样式互不干扰）、插槽分发（组件定义占位符、业务方填充内容，注意插槽是投影不是移动）、设计系统组件库（升级组件只改一处，全项目同步生效）。Chrome 54+ / Safari 10.1+ / Firefox 63+ 全绿。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>标签名必须含短横线（<code>&lt;my-button&gt;</code> 合法，<code>&lt;mybutton&gt;</code> 报错）——避免与原生冲突。</li><li>Shadow DOM 样式完全隔离；穿透用 CSS 自定义属性 --*。</li><li>生命周期顺序：constructor → connectedCallback → attributeChangedCallback。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么自定义元素标签名必须包含短横线（如 <code>&lt;neon-card&gt;</code>），而不能是 <code>&lt;neoncard&gt;</code>？</p><p><strong>答</strong>：HTML 规范保证原生元素永远不会带短横线，强制短横线等于给自定义元素划出独立命名空间，永久避免与未来新增原生元素撞名。<code>customElements.define</code> 遇到无短横线的名字会直接抛 <code>SyntaxError</code>。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>template 克隆 + neon-card 三插槽 + neon-button 三变体 + live-counter 属性监听：<a href="./../../examples/html/16-web-components/index-01-web-components.html">examples/html/16-web-components/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 45 话《@layer 进阶》——层叠层基础用熟了？嵌套层、匿名层、revert-layer 三连，让第三方库样式想压就压、想掀就掀。</p>',22)])])}const u=a(l,[["render",r]]);export{p as __pageData,u as default};
